public void initValue()
{
    super();

    this.Status     = UTCSFCustomerPushStatus::Pending;
    this.RetryCount = 0;

    if (!this.SourceChannel)
    {
        this.SourceChannel = 'D365FO';
    }
}

public static UTCSFCustomerPushQueue findByRecId(RecId _recId, boolean _forUpdate = false)
{
    UTCSFCustomerPushQueue queueRecord;

    if (_recId)
    {
        queueRecord.selectForUpdate(_forUpdate);

        select firstonly queueRecord
            where queueRecord.RecId == _recId;
    }

    return queueRecord;
}

/// <summary>
/// Finds an existing Pending queue record for the given customer account to prevent duplicate queue bursts.
/// </summary>
/// <param name = "_custAccount">Customer account number.</param>
/// <param name = "_forUpdate">True to select the record for update.</param>
/// <returns>The pending <c>UTCSFCustomerPushQueue</c> record if found.</returns>
public static UTCSFCustomerPushQueue findPendingByCustAccount(CustAccount _custAccount, boolean _forUpdate = false)
{
    UTCSFCustomerPushQueue queueRecord;

    if (_custAccount)
    {
        queueRecord.selectForUpdate(_forUpdate);

        select firstonly queueRecord
            index CustAccountStatusIdx
            where queueRecord.CustAccount == _custAccount
               && queueRecord.Status      == UTCSFCustomerPushStatus::Pending;
    }

    return queueRecord;
}

/// <summary>
/// Appends a customer record to the staging queue for asynchronous push to Salesforce.
/// Uses append-only insert (no <c>forupdate</c> lookup) to avoid SQL lock contention and
/// <c>UpdateConflict</c> aborts inside active ERP/POS customer transactions; deduplication
/// is performed safely during asynchronous batch processing.
/// </summary>
/// <param name = "_custAccount">The customer account in company 'utc'.</param>
/// <param name = "_sourceChannel">Source channel (e.g., 'POS', 'D365FO', 'E-Comm').</param>
/// <param name = "_operatingUnitNumber">Store/Operating unit number if applicable.</param>
/// <param name = "_terminal">Retail POS terminal ID if applicable.</param>
/// <returns>The inserted <c>UTCSFCustomerPushQueue</c> record.</returns>
public static UTCSFCustomerPushQueue enqueue(
    CustAccount           _custAccount,
    UTCSFSourceChannel    _sourceChannel       = 'D365FO',
    OMOperatingUnitNumber _operatingUnitNumber = '',
    RetailTerminalId      _terminal            = '')
{
    UTCSFCustomerPushQueue queueRecord;

    if (!_custAccount)
    {
        return queueRecord;
    }

    ttsbegin;

    queueRecord.clear();
    queueRecord.initValue();
    queueRecord.CustAccount         = _custAccount;
    queueRecord.SourceChannel       = _sourceChannel ? _sourceChannel : 'D365FO';
    queueRecord.OperatingUnitNumber = _operatingUnitNumber;
    queueRecord.Terminal            = _terminal;
    queueRecord.Status              = UTCSFCustomerPushStatus::Pending;
    queueRecord.RetryCount          = 0;
    queueRecord.insert();

    ttscommit;

    return queueRecord;
}

/// <summary>
/// Atomically transitions a queue record from Pending to Processing.
/// </summary>
/// <param name = "_queueRecId">RecId of the queue item.</param>
/// <returns>True if the record was successfully claimed for processing.</returns>
public static boolean markProcessing(RecId _queueRecId)
{
    UTCSFCustomerPushQueue queueRecord;
    boolean                claimed = false;

    ttsbegin;

    select firstonly forupdate queueRecord
        where queueRecord.RecId  == _queueRecId
           && queueRecord.Status == UTCSFCustomerPushStatus::Pending;

    if (queueRecord.RecId != 0)
    {
        queueRecord.Status = UTCSFCustomerPushStatus::Processing;
        queueRecord.update();
        claimed = true;
    }

    ttscommit;

    return claimed;
}

/// <summary>
/// Safely resets a claimed <c>Processing</c> record back to <c>Pending</c> (for example when
/// the integration is temporarily disabled) so it is never stranded in <c>Processing</c>.
/// </summary>
/// <param name = "_queueRecId">RecId of the queue item.</param>
public static void resetToPending(RecId _queueRecId)
{
    UTCSFCustomerPushQueue queueRecord;

    if (!_queueRecId)
    {
        return;
    }

    ttsbegin;

    select firstonly forupdate queueRecord
        where queueRecord.RecId  == _queueRecId
           && queueRecord.Status == UTCSFCustomerPushStatus::Processing;

    if (queueRecord.RecId != 0)
    {
        queueRecord.Status = UTCSFCustomerPushStatus::Pending;
        queueRecord.update();
    }

    ttscommit;
}

/// <summary>
/// Recovers queue records stranded in <c>Processing</c> state (e.g. after an AOS recycle or worker crash)
/// by resetting any record older than <c>_staleMinutes</c> back to <c>Pending</c>.
/// </summary>
/// <param name = "_staleMinutes">Age threshold in minutes before a Processing record is considered stale.</param>
/// <returns>Number of recovered records.</returns>
public static int recoverStaleProcessingRecords(int _staleMinutes = 15)
{
    UTCSFCustomerPushQueue queueRecord;
    int                    staleThreshold = _staleMinutes > 0 ? _staleMinutes : 15;
    utcdatetime            cutoffUtc      = DateTimeUtil::addMinutes(DateTimeUtil::utcNow(), -staleThreshold);
    int                    recoveredCount = 0;

    ttsbegin;

    while select forupdate queueRecord
        where queueRecord.Status           == UTCSFCustomerPushStatus::Processing
           && queueRecord.ModifiedDateTime <= cutoffUtc
    {
        queueRecord.Status    = UTCSFCustomerPushStatus::Pending;
        queueRecord.LastError = strFmt('Recovered from stale Processing state after %1 minutes.', staleThreshold);
        queueRecord.update();
        recoveredCount++;
    }

    ttscommit;

    return recoveredCount;
}

/// <summary>
/// Marks a queue item as Succeeded after a 2xx response from Salesforce.
/// </summary>
public static void markSucceeded(
    RecId                    _queueRecId,
    UTCSFRequestId           _requestId   = '',
    UTCSFSalesforceAccountId _sfAccountId = '')
{
    UTCSFCustomerPushQueue queueRecord;

    ttsbegin;

    queueRecord = UTCSFCustomerPushQueue::findByRecId(_queueRecId, true);
    if (queueRecord.RecId != 0)
    {
        queueRecord.Status              = UTCSFCustomerPushStatus::Succeeded;
        queueRecord.LastRequestId       = _requestId;
        queueRecord.SalesforceAccountId = _sfAccountId;
        queueRecord.LastError           = '';
        queueRecord.ProcessedDateTime   = DateTimeUtil::utcNow();
        queueRecord.update();
    }

    ttscommit;
}

/// <summary>
/// Updates the queue record after a failed push attempt.
/// HTTP 400 Bad Request sets <c>_isPermanentFailure = true</c> so the record is never retried.
/// Transient failures increment <c>RetryCount</c> and remain Pending until <c>MaxRetryCount</c> is reached.
/// </summary>
public static void markFailed(
    RecId          _queueRecId,
    str            _errorMessage,
    boolean        _isPermanentFailure = false,
    UTCSFRequestId _requestId          = '')
{
    UTCSFCustomerPushQueue     queueRecord;
    UTCSFIntegrationParameters parameters = UTCSFIntegrationParameters::find();
    int                        maxRetries = parameters.MaxRetryCount > 0 ? parameters.MaxRetryCount : 3;

    ttsbegin;

    queueRecord = UTCSFCustomerPushQueue::findByRecId(_queueRecId, true);
    if (queueRecord.RecId != 0)
    {
        queueRecord.RetryCount        = queueRecord.RetryCount + 1;
        queueRecord.LastError         = _errorMessage;
        queueRecord.LastRequestId     = _requestId;
        queueRecord.ProcessedDateTime = DateTimeUtil::utcNow();

        if (_isPermanentFailure || queueRecord.RetryCount >= maxRetries)
        {
            queueRecord.Status = UTCSFCustomerPushStatus::Failed;
        }
        else
        {
            queueRecord.Status = UTCSFCustomerPushStatus::Pending;
        }

        queueRecord.update();
    }

    ttscommit;
}
